def all_starts(o):
    if isinstance(o, dict):
        for k, v in o.items():
            if k == "start" and isinstance(v, (int, float)): yield v
            else: yield from all_starts(v)
    elif isinstance(o, list):
        for v in o: yield from all_starts(v)
